<div class="page-header"><div><p class="eyebrow">STUDENT MANAGEMENT</p><h1>Edit student</h1><p>Update profile and academic placement. Existing grade records remain intact.</p></div><a href="/students" class="btn btn-outline-secondary">Back to students</a></div>
<section class="panel"><form method="post" action="/students/update" enctype="multipart/form-data" data-validate><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$record['id'] ?>"><div class="form-grid">
<label class="form-label">First name<input class="form-control" name="first_name" value="<?= e($record['first_name']) ?>" maxlength="75" required></label>
<label class="form-label">Last name<input class="form-control" name="last_name" value="<?= e($record['last_name']) ?>" maxlength="75" required></label>
<label class="form-label">Email<input type="email" class="form-control" name="email" value="<?= e($record['email']) ?>" maxlength="254" required></label>
<label class="form-label">Matriculation number<input class="form-control" name="matriculation_number" value="<?= e($record['matriculation_number']) ?>" maxlength="40" required></label>
<label class="form-label">Programme<select class="form-select" name="programme_id" required><?php foreach($programmes as $r):?><option value="<?= (int)$r['id'] ?>" <?= (int)$r['id']===(int)$record['programme_id']?'selected':'' ?> <?= $r['status']!=='active'?'disabled':'' ?>><?= e($r['department'].' · '.$r['name']) ?></option><?php endforeach;?></select></label>
<label class="form-label">Academic level<select class="form-select" name="academic_level_id" required><?php foreach($levels as $r):?><option value="<?= (int)$r['id'] ?>" <?= (int)$r['id']===(int)$record['academic_level_id']?'selected':'' ?> <?= $r['status']!=='active'?'disabled':'' ?>><?= e($r['name']) ?></option><?php endforeach;?></select></label>
<label class="form-label">Phone<input class="form-control" type="tel" name="phone" maxlength="30" value="<?= e($record['phone']) ?>"></label>
<label class="form-label">Gender<select class="form-select" name="gender"><option value="">Not specified</option><?php foreach(['female'=>'Female','male'=>'Male','other'=>'Other','prefer_not_to_say'=>'Prefer not to say'] as $value=>$label):?><option value="<?= e($value) ?>" <?= ($record['gender']??'')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label>
<label class="form-label">Date of birth<input class="form-control" type="date" name="date_of_birth" value="<?= e($record['date_of_birth']) ?>"></label>
<label class="form-label">Admission year<input class="form-control" type="number" name="admission_year" min="1901" max="2155" value="<?= e($record['admission_year']) ?>"></label>
<label class="form-label">Replace passport image (optional; max 2 MB)<input class="form-control" type="file" name="passport" accept="image/jpeg,image/png,image/webp"></label>
</div><p class="form-hint">Programme and level changes are blocked while the student has current-semester registrations. Photos remain private.</p><button type="submit" class="btn btn-primary">Update student</button></form></section>
